import type {ViewContext} from '@/src/archive/views';
import type {GoogleExports} from './on_Snapshot__53_googledocs';

export function exportEvidence({capture,archive}:ViewContext){
  const hook=capture?.hooks.find(hook=>hook.plugin==='googledocs') || archive.metadata?.plugins?.find((plugin:{id:string})=>plugin.id==='googledocs')?.hooks?.[0];
  return hook?.data as GoogleExports|undefined;
}

// Source-ported from abx-plugins/googledocs/googledocs_utils.js. See ../README.md.
const FORMATS = {
  document: ["docx", "pdf", "odt", "rtf", "txt", "md", "zip", "epub"],
  spreadsheets: ["xlsx", "csv", "pdf", "ods", "tsv", "zip"],
  presentation: ["pptx", "pdf", "odp", "txt"],
  drawings: ["svg", "pdf", "png", "jpg"],
};

function parseDocumentUrl(value) {
  try {
    const url = new URL(value);
    if (
      url.protocol !== "https:" ||
      url.host !== "docs.google.com" ||
      url.username ||
      url.password
    )
      return null;
    const match = url.pathname.match(
      /^\/(?:a\/[^/]+\/)?(document|spreadsheets|presentation|drawings)(\/u\/\d+)?\/d\/([\w-]+)(?:\/|$)/
    );
    if (!match || match[3] === "e") return null; // Published IDs are not file IDs.
    return {
      kind: match[1],
      id: match[3],
      base: `https://docs.google.com${match[0].replace(/\/$/, "")}`,
      authuser: url.searchParams.get("authuser") || match[2]?.split("/").pop(),
      resourcekey: url.searchParams.get("resourcekey"),
      gid:
        url.searchParams.get("gid") ||
        new URLSearchParams(url.hash.slice(1)).get("gid"),
    };
  } catch {
    return null;
  }
}

function exportUrl(doc, format) {
  if (!FORMATS[doc.kind]?.includes(format))
    throw new Error(`Unsupported export format: ${format}`);
  const url = new URL(`${doc.base}/export`);
  if (["presentation", "drawings"].includes(doc.kind))
    url.pathname += `/${format === "jpg" ? "jpeg" : format}`;
  else url.searchParams.set("format", format);
  for (const key of ["authuser", "resourcekey"]) {
    if (doc[key]) url.searchParams.set(key, doc[key]);
  }
  if (["csv", "tsv"].includes(format) && /^\d+$/.test(doc.gid || ""))
    url.searchParams.set("gid", doc.gid);
  return url.href;
}

async function discoverSheets(page) {
  // The editor's initial model includes every worksheet, including tabs that
  // are offscreen. Read its embedded JSON without switching tabs or fetching
  // metadata. Google clears window.bootstrapData after loading the editor.
  const sheets = await page.evaluate(() => {
    for (const script of document.scripts) {
      const match = script.textContent.match(
        /var bootstrapData\s*=\s*(\{.*\});\s*function loadWaffle/s
      );
      if (!match) continue;
      const records = JSON.parse(match[1]).changes?.topsnapshot;
      if (!Array.isArray(records)) break;
      // 21350203 is the worksheet-definition record in Google's editor model.
      return records
        .filter((record) => record[0] === 21350203)
        .map((record) => {
          const sheet = JSON.parse(record[1]);
          const name = sheet[3]
            ?.flatMap((properties) => properties["1"] || [])
            .find(
              (property) => property[0] === 0 && typeof property[2] === "string"
            )?.[2];
          return { id: sheet[2], name };
        });
    }
    return [];
  });
  if (
    !sheets.length ||
    sheets.some(
      (sheet) => !/^\d+$/.test(sheet.id) || typeof sheet.name !== "string"
    ) ||
    new Set(sheets.map((sheet) => sheet.id)).size !== sheets.length
  ) {
    throw new Error(
      "Unable to discover all sheets from the loaded Google editor"
    );
  }
  return sheets;
}

function validateExport(body, format, mimeType) {
  const bytes = body.subarray(0, 1024);
  const length = bytes.length;
  const text = new TextDecoder().decode(bytes).trimStart();
  const mime = (mimeType || "").split(";")[0].trim().toLowerCase();
  if (
    !length ||
    /html|json/.test(mime) ||
    /^(?:<!doctype\s+html|<html\b)/i.test(text)
  )
    throw new Error("Export returned an empty file or login/error page");
  let valid = false;
  if (
    ["docx", "xlsx", "pptx", "odt", "ods", "odp", "zip", "epub"].includes(
      format
    )
  )
    valid = [80, 75, 3, 4].every((value, index) => bytes[index] === value);
  else if (format === "pdf") valid = text.startsWith("%PDF-");
  else if (format === "png")
    valid = [137, 80, 78, 71, 13, 10, 26, 10].every((value, index) => bytes[index] === value);
  else if (format === "jpg")
    valid = bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255;
  else if (format === "svg")
    valid =
      mime === "image/svg+xml" && /^(?:<\?xml[^>]*>\s*)?<svg\b/.test(text);
  else if (format === "rtf") valid = text.startsWith("{\\rtf");
  else
    valid = [
      "text/plain",
      "text/csv",
      "text/tab-separated-values",
      "text/markdown",
      "text/x-markdown",
    ].includes(mime);
  if (!valid)
    throw new Error(
      `Invalid ${format.toUpperCase()} export (${
        mime || "missing Content-Type"
      })`
    );
}


export {FORMATS, parseDocumentUrl, exportUrl, discoverSheets, validateExport};

import type {ViewContext} from '@/src/archive/views';
import {exportEvidence} from './model';
export default (context:ViewContext)=>!!exportEvidence(context)?.exports.length;

import type {ViewContext,ViewResult} from '@/src/archive/views';
import {recordURL} from '@/src/archive/replay';
import template from '@/vendor/archivebox/plugins/googledocs/full.html?raw';
import {exportEvidence} from './model';
import {initializeGoogleDocs} from './template';

export default async function(context:ViewContext):Promise<ViewResult>{
  const {archive}=context,evidence=exportEvidence(context);
  if(!evidence)throw Error('No Google document exports recorded');
  const entries=new Map(evidence.exports.map(item=>[item.path,archive.find(item.ref.url,item.ref.ts)]));
  const data={...evidence,exports:await Promise.all(evidence.exports.map(async item=>{
    const entry=entries.get(item.path);if(!entry)throw Error(`Missing recorded export: ${item.path}`);
    const headers=await archive.headers(entry);
    return {...item,size:Number(headers.headers['content-length']||0),digest:entry.digest};
  }))};
  return {title:'Google Docs',summary:'',sections:[],presentation:{type:'canonical',plugin:'googledocs',title:'Google Docs',template,data,filename:'exports.json',nativePDF:true,
    async initialize(document,data,options){
      const urls=new Map<string,string>();
      const entry=(item:{path:string})=>{const value=entries.get(item.path);if(!value)throw Error(`Missing recorded export: ${item.path}`);return value};
      try{
        await initializeGoogleDocs(document,data,{rawURL:options.rawURL,url:item=>recordURL(archive,entry(item)),download:async item=>{
          // Browser downloads bypass the replay service worker. Materialize only
          // the clicked original response, as with the gallery/media viewers.
          const resource=entry(item),{body}=await archive.read(resource);
          const href=URL.createObjectURL(new Blob([body as BlobPart],{type:resource.mime}));
          const link=globalThis.document.createElement('a');link.href=href;link.download=item.path;link.click();
          setTimeout(()=>URL.revokeObjectURL(href),60000);
        },pdf:async item=>{
          let url=urls.get(item.path);
          if(!url){const {body}=await archive.read(entry(item));url=URL.createObjectURL(new Blob([body as BlobPart],{type:'application/pdf'}));urls.set(item.path,url)}
          return url;
        }});
      }catch(error){urls.forEach(url=>URL.revokeObjectURL(url));throw error}
      return ()=>urls.forEach(url=>URL.revokeObjectURL(url));
    },
  }};
}

// Original googledocs/full.html initializer; WACZ resource URLs replace relative files.
export async function initializeGoogleDocs(document, manifest, options) {
        const byId = (id) => document.getElementById(id),
          el = (tag, text, cls) => {
            const node = document.createElement(tag);
            if (text != null) node.textContent = text;
            if (cls) node.className = cls;
            return node;
          };
        const raw = value => String(value);
        byId('raw').href = options.rawURL;
        const labels = {
          docx: "Word document",
          xlsx: "Excel workbook",
          pptx: "PowerPoint",
          pdf: "PDF document",
          csv: "CSV spreadsheet",
          tsv: "TSV spreadsheet",
          odt: "OpenDocument text",
          ods: "OpenDocument sheet",
          odp: "OpenDocument slides",
          txt: "Plain text",
          md: "Markdown",
          rtf: "Rich text",
          zip: "HTML & assets",
          epub: "EPUB ebook",
          svg: "Vector drawing",
          png: "PNG image",
          jpg: "JPEG image",
        };
        const sizeLabel = (size) =>
          size >= 1048576
            ? (size / 1048576).toFixed(1) + " MB"
            : size >= 1024
            ? Math.ceil(size / 1024) + " KB"
            : size + " B";
        let exports = [],
          selectedSheet,
          currentFormat,
          selection = 0;
        byId("sheet").addEventListener("change", () => {
          const item = exports.find(
            (file) =>
              file.format === currentFormat &&
              file.sheet_id === byId("sheet").value
          );
          if (item) select(item);
        });
        async function readText(url) {
          const response = await fetch(raw(url));
          if (!response.ok) throw Error("Preview unavailable");
          const reader = response.body.getReader(),
            decoder = new TextDecoder();
          let text = "",
            bytes = 0;
          try {
            while (bytes < 262144) {
              const { done, value } = await reader.read();
              if (done)
                return { text: text + decoder.decode(), truncated: false };
              const part = value.subarray(0, 262144 - bytes);
              bytes += part.length;
              text += decoder.decode(part, { stream: true });
            }
            return { text, truncated: true };
          } finally {
            await reader.cancel();
          }
        }
        function csvRows(text, delimiter) {
          const rows = [];
          let row = [],
            cell = "",
            quoted = false;
          for (let i = 0; i < text.length; i++) {
            const c = text[i];
            if (c === '"') {
              if (quoted && text[i + 1] === '"') {
                cell += '"';
                i++;
              } else quoted = !quoted;
            } else if (c === delimiter && !quoted) {
              row.push(cell);
              cell = "";
            } else if ((c === "\n" || c === "\r") && !quoted) {
              if (c === "\r" && text[i + 1] === "\n") i++;
              row.push(cell);
              rows.push(row);
              row = [];
              cell = "";
              if (rows.length >= 201) break;
            } else cell += c;
          }
          if (rows.length < 201 && (cell || row.length))
            rows.push([...row, cell]);
          return rows;
        }
        async function select(item) {
          const generation = ++selection,
            preview = byId("preview"),
            note = byId("note");
          preview.replaceChildren();
          note.hidden = true;
          currentFormat = item.format;
          if (item.sheet_id != null) selectedSheet = item.sheet_id;
          const sheets = exports.filter(
            (file) => file.format === item.format && file.sheet_id != null
          );
          byId("sheet-control").hidden = !sheets.length;
          byId("sheet").replaceChildren(
            ...sheets.map((file) => {
              const option = el("option", file.sheet_name || file.sheet_id);
              option.value = file.sheet_id;
              option.selected = file.sheet_id === selectedSheet;
              return option;
            })
          );
          for (const button of byId("formats").children)
            button.setAttribute(
              "aria-pressed",
              String(button.dataset.format === item.format)
            );
          byId("preview-title").textContent = labels[item.format];
          const url = options.url(item),
            download = byId("download");
          download.href = raw(url);
          download.download = item.path;
          download.hidden = false;
          download.textContent = "⤓ Download " + item.format.toUpperCase();
          download.onclick = event => {
            event.preventDefault();
            void options.download(item).catch(error => {
              note.textContent = error.message;
              note.hidden = false;
            });
          };
          const pdf = exports.find((file) => file.format === "pdf");
          if (
            item.format === "pdf" ||
            (!["csv", "tsv", "txt", "md", "svg", "png", "jpg"].includes(
              item.format
            ) &&
              pdf)
          ) {
            const frame = el("iframe");
            frame.title = "Archived document PDF";
            const pdfURL = await options.pdf(pdf);
            if (generation !== selection) return;
            frame.src = pdfURL + "#view=FitH";
            preview.append(frame);
            if (item.format !== "pdf") {
              note.textContent =
                "PDF preview · Download " +
                item.format.toUpperCase() +
                " for the original export.";
              note.hidden = false;
            }
            return;
          }
          if (["svg", "png", "jpg"].includes(item.format)) {
            const image = el("img", null, "image");
            image.alt = "Archived drawing";
            image.src = raw(url);
            preview.append(image);
            return;
          }
          if (!["csv", "tsv", "txt", "md"].includes(item.format)) {
            const empty = el("div", null, "empty");
            empty.append(
              el("strong", labels[item.format]),
              el(
                "span",
                "Download this export to open it in a compatible application."
              )
            );
            preview.append(empty);
            return;
          }
          try {
            const { text, truncated } = await readText(url);
            if (generation !== selection) return;
            if (["csv", "tsv"].includes(item.format)) {
              const rows = csvRows(text, item.format === "csv" ? "," : "\t"),
                table = el("table"),
                head = el("thead"),
                body = el("tbody");
              rows.forEach((row, index) => {
                const tr = el("tr");
                for (const cell of row.slice(0, 30))
                  tr.append(el(index === 0 ? "th" : "td", cell));
                (index === 0 ? head : body).append(tr);
              });
              table.append(head, body);
              preview.append(table);
              note.textContent =
                (item.sheet_name || "Single-sheet export") +
                (rows.length >= 201 || truncated
                  ? " · Showing the first 200 rows"
                  : "") +
                (rows.some((row) => row.length > 30)
                  ? " · First 30 columns"
                  : "");
              note.hidden = false;
            } else {
              preview.append(el("pre", text));
              if (truncated) {
                note.textContent =
                  "Preview truncated · Download the complete file above.";
                note.hidden = false;
              }
            }
          } catch (error) {
            if (generation === selection)
              preview.append(el("p", error.message, "empty"));
          }
        }
        await Promise.resolve(manifest)
          .then((manifest) => {
            document.body.dataset.kind = manifest.document_type;
            byId("title").textContent = manifest.title || "Google Docs exports";
            exports = (manifest.exports || []).filter(
              (item) =>
                Object.hasOwn(labels, item.format) &&
                (item.path === "document." + item.format ||
                  (["csv", "tsv"].includes(item.format) &&
                    /^\d+$/.test(item.sheet_id) &&
                    item.path === "sheet-" + item.sheet_id + "." + item.format))
            );
            selectedSheet = manifest.selected_sheet;
            const formats = [...new Set(exports.map((item) => item.format))];
            const sheetCount = new Set(
              exports
                .filter((item) => item.sheet_id != null)
                .map((item) => item.sheet_id)
            ).size;
            byId("summary").textContent =
              formats.length +
              " formats · " +
              (sheetCount ? sheetCount + " sheets · " : "") +
              sizeLabel(
                exports.reduce((sum, item) => sum + (Number(item.size) || 0), 0)
              );
            byId("errors").textContent = (manifest.errors || [])
              .map(
                (item) =>
                  item.format.toUpperCase() +
                  (item.sheet_name ? " (" + item.sheet_name + ")" : "") +
                  ": " +
                  item.error
              )
              .join("\n");
            for (const format of formats) {
              const items = exports.filter((item) => item.format === format);
              const button = el("button", format.toUpperCase(), "format");
              button.type = "button";
              button.dataset.format = format;
              button.title =
                labels[format] +
                " · " +
                sizeLabel(items.reduce((sum, item) => sum + item.size, 0));
              button.setAttribute("aria-pressed", "false");
              button.addEventListener("click", () =>
                select(
                  items.find((item) => item.sheet_id === selectedSheet) ||
                    items[0]
                )
              );
              byId("formats").append(button);
            }
            const preferredFormat = manifest.document_type === "spreadsheets" ? "csv" : "pdf";
            const initial =
              exports.find((item) => item.format === preferredFormat && item.sheet_id === selectedSheet) ||
              exports.find((item) => item.format === preferredFormat) || exports[0];
            if (initial) return select(initial);
            else
              byId("preview").replaceChildren(
                el("p", "No exports saved", "empty")
              );
          })
          .catch((error) =>
            byId("preview").replaceChildren(el("p", error.message, "empty"))
          );
      }

export type GoogleDocument = {kind:'document'|'spreadsheets'|'presentation'|'drawings';id:string;base:string;authuser?:string|null;resourcekey?:string|null;gid?:string|null};
export type Sheet = {id:string;name:string};
export const FORMATS: Record<GoogleDocument['kind'],string[]>;
export function parseDocumentUrl(value:string):GoogleDocument|null;
export function exportUrl(doc:GoogleDocument,format:string):string;
export function discoverSheets(page:{evaluate:(fn:()=>unknown)=>Promise<unknown>}):Promise<Sheet[]>;
export function validateExport(body:Uint8Array,format:string,mimeType:string):void;

import type {ViewContext} from '@/src/archive/views';
import {cardDocument,cardHTML,cardElement} from '@/src/archive/cards';
import template from '@/vendor/archivebox/plugins/googledocs/card.html?raw';
import {exportEvidence} from './model';
export default async function(context:ViewContext){
  const data=exportEvidence(context),doc=cardDocument(template);
  doc.getElementById('title')!.textContent=data?.title||'Google Docs exports';
  for(const format of new Set(data?.exports.map(item=>item.format)||[]))doc.getElementById('formats')!.append(cardElement(doc,'span',format.toUpperCase(),'badge'));
  return cardHTML(doc);
}

import {createRequire} from 'node:module';
import {readdirSync,readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const require=createRequire(import.meta.url);
/** Include copied Python/WASM assets as well as Vite's content-hashed code in
 * the offline derivation cache identity, including locally patched wheels. */
export function pythonRuntimeRevision(){
  const root=fileURLToPath(new URL('../public/',import.meta.url));
  const files=browserAssets().filter(asset=>asset.relativeDest.startsWith('pyodide/')).map(asset=>asset.absoluteSrc);
  for(const folder of ['pyodide','gallery-dl','forum-dl','papers-dl','ytdlp']){
    for(const file of readdirSync(path.join(root,folder),{withFileTypes:true,recursive:true}))if(file.isFile())files.push(path.join(file.parentPath,file.name));
  }
  const hash=createHash('sha256');
  for(const file of files.sort()){hash.update(path.basename(file));hash.update(readFileSync(file))}
  return hash.digest('hex');
}
export function browserAssets(){
  const assets:{absoluteSrc:string;relativeDest:string}[]=[];
  const add=(directory:string,destination:string,accept:((name:string)=>boolean)=()=>true)=>{
    for(const file of readdirSync(directory,{withFileTypes:true,recursive:true}))if(file.isFile()&&accept(file.name)){
      const absoluteSrc=path.join(file.parentPath,file.name);assets.push({absoluteSrc,relativeDest:path.join(destination,path.relative(directory,absoluteSrc))});
    }
  };
  const root=path.dirname(require.resolve('pyodide/package.json'));
  add(root,'pyodide',name=>['pyodide.asm.js','pyodide.asm.wasm','python_stdlib.zip','pyodide-lock.json'].includes(name));
  const paddleRequire=createRequire(path.resolve('node_modules/@paddleocr/paddleocr-js/package.json'));
  add(path.dirname(paddleRequire.resolve('onnxruntime-web')),'ocr/ort',name=>/^ort-wasm-simd-threaded\.jsep\.(mjs|wasm)$/.test(name));
  // Package the real FFmpeg worker/core; replay never loads executable code from a CDN.
  add(path.dirname(require.resolve('@ffmpeg/ffmpeg/worker')),'ytdlp/ffmpeg/worker',name=>name.endsWith('.js'));
  add(path.join(path.dirname(require.resolve('@ffmpeg/core')),'../esm'),'ytdlp/ffmpeg/core',name=>/\.(js|wasm)$/.test(name));
  return assets;
}

import MiniSearch from 'minisearch';
import {cardDocument,cardHTML} from '../archive/cards';
import type {CanonicalPresentation} from '../archive/views';
import fullTemplate from '../../vendor/archivebox/plugins/parse_rss_urls/full.html?raw';
import {searchOptions,type SearchIndex,type SearchDocument} from '../../abx-plugins/abx_plugins/plugins/search_contents/browser/index';
function searchLayout(document:Document,total:number){
  const el=(tag:string,text?:unknown,cls?:string)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(cls)node.className=cls;return node};
  const content=document.getElementById('content')!,stats=el('section',undefined,'panel stats'),count=el('span',undefined,'badge');count.textContent=`${total} documents`;stats.append(count);content.append(stats);
  const panel=el('section',undefined,'panel'),search=document.createElement('input'),rows=el('div',undefined,'rows'),more=document.createElement('button');search.type='search';search.className='filter';search.placeholder='Search archived text…';search.setAttribute('aria-label','Search archived text');more.textContent='Show more';panel.append(search,rows);content.append(panel);
  return {el,panel,search,rows,more,count};
}
export function searchCard(total:number){
 const doc=cardDocument(fullTemplate);searchLayout(doc,total);return cardHTML(doc);
}
export function searchPresentation(data:SearchIndex,read:(document:SearchDocument)=>Promise<string>):CanonicalPresentation {
 return {type:'canonical',plugin:'search_contents',title:'Search',template:fullTemplate.replaceAll('Discovered URLs','Search'),data,filename:'index.json',async initialize(document,data:SearchIndex,options){
  const index=await MiniSearch.loadJSAsync(data.index,searchOptions);
  const {el,panel,search,rows,more,count}=searchLayout(document,data.documents.length);
  const previews=new WeakMap<Element,()=>Promise<void>>(),observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){observer.unobserve(entry.target);void previews.get(entry.target)?.()}},{root:document.documentElement,rootMargin:'200px'});
  let matches:SearchDocument[]=[],position=0,generation=0;
  function append(){
   const needle=search.value.trim().toLocaleLowerCase(),terms=needle.split(/\s+/).filter(Boolean),current=generation;
   for(const entry of matches.slice(position,position+40)){
    const row=el('article',undefined,'row'),body=el('div'),title=el('a',entry.title,'url') as HTMLAnchorElement;
    const archivedURL=options.resourceURL(entry.url);if(archivedURL){title.href=archivedURL.replace(/(\d{14,17})id_\//,'$1mp_/');title.target='_blank';title.rel='noopener'}
    body.append(title,el('div',entry.ref.member?.join(' / ')||entry.url,'muted'));const excerpt=el('p');body.append(excerpt);row.append(el('div',++position,'number'),body);rows.append(row);
    previews.set(row,async()=>{
     try{
      const text=await read(entry);if(current!==generation)return;
      const lower=text.toLocaleLowerCase(),exact=needle?lower.indexOf(needle):-1;
      const hit=exact>=0?needle:terms.find(term=>lower.includes(term))||'',offset=hit?lower.indexOf(hit):0,start=Math.max(0,offset-120);
      if(hit)excerpt.append(document.createTextNode(text.slice(start,offset)),el('mark',text.slice(offset,offset+hit.length)),document.createTextNode(text.slice(offset+hit.length,offset+hit.length+240)));
      else excerpt.textContent=text.slice(0,360);
     }catch(error){if(current===generation)excerpt.textContent=String(error)}
    });observer.observe(row);
   }
   if(position>=matches.length)more.remove();else panel.append(more);
  }
  function render(){
   generation++;observer.disconnect();rows.replaceChildren();position=0;
   const query=search.value.trim();matches=query?index.search(query).map(result=>data.documents[Number(result.id)]!):data.documents;
   count.textContent=query?`${matches.length} matching documents`:`${matches.length} documents`;
   if(!matches.length)rows.append(el('div',query?'No matching documents':'No text documents archived','empty'));
   append();
  }
  search.addEventListener('input',render);more.addEventListener('click',append);render();return()=>{generation++;observer.disconnect()};
 }};
}

import template from '../../vendor/archivebox/directory_index.html?raw';
import {downloadZip} from 'client-zip';

export type DirectoryFile = {
  path:string; mime:string; size?:number; title?:string; href?:string;
  url?:string|(()=>Promise<string>); read:()=>Promise<Blob>;
  open?:()=>void|Promise<void>;
};
export type DirectoryOptions = {title:string; files:DirectoryFile[]; snapshot?:()=>void; output?:()=>void};

// ArchiveBox static/directory_index.html, with only the filesystem adapter replaced.
// A shadow root keeps the original styles out of the surrounding plugin document.
const css=template.match(/<style>([\s\S]*?)<\/style>/)![1]!
  .replace(':root',':host').replace('html, body',':host').replace('@media (max-width: 640px)','@container (max-width: 640px)').replace('.size-column { width: 65px; }','.size-column { width: 80px; }');
const markup=template.match(/<main>[\s\S]*?<\/main>/)![0];
const bytes=(size?:number)=>size===undefined?'—':size<1024?`${size} B`:size<1048576?`${(size/1024).toFixed(1)} KB`:size<1073741824?`${(size/1048576).toFixed(1)} MB`:`${(size/1073741824).toFixed(2)} GB`;
const valid=(path:string)=>path&&!path.startsWith('/')&&!path.includes('\\')&&!path.includes('\0')&&!path.split('/').some(part=>!part||part==='.'||part==='..');

export function mountDirectoryBrowser(host:HTMLElement,options:DirectoryOptions):()=>void {
  const document=host.ownerDocument,root=host.shadowRoot||host.attachShadow({mode:'open'});
  root.innerHTML=`<style>${css}\n:host{display:block;container-type:inline-size;min-width:0} [hidden]{display:none!important} button{font:inherit} .directory-toolbar button{cursor:pointer;color:inherit} .directory-error{color:#b42318;padding:8px 12px} .directory-title{min-width:0} </style>${markup}`;
  const el=<K extends keyof HTMLElementTagNameMap>(tag:K,text?:string,cls?:string)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node};
  const get=<T extends Element=HTMLElement>(selector:string)=>root.querySelector<T>(selector)!;
  const tbody=get<HTMLTableSectionElement>('tbody'),filter=get<HTMLInputElement>('#filter-files'),toolbar=get('.directory-toolbar');
  let prefix='',sortKey='name',direction=1,disposed=false,generation=0;
  const urls=new Set<string>(),files=options.files.filter(file=>valid(file.path));
  const report=(reason:unknown)=>{if(disposed)return;const error=get('.directory-error');error.textContent=String(reason);error.removeAttribute('hidden')};
  const objectURL=(blob:Blob)=>{if(disposed)throw new DOMException('Directory closed','AbortError');const url=URL.createObjectURL(blob);urls.add(url);return url};
  const save=(blob:Blob,name:string)=>{if(disposed)return;const url=objectURL(blob),link=el('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>{URL.revokeObjectURL(url);urls.delete(url)},60000)};
  const busy=async(link:HTMLElement,run:()=>Promise<void>)=>{if(link.getAttribute('aria-busy')==='true')return;link.setAttribute('aria-busy','true');link.classList.add('is-loading');try{await run()}catch(error){report(error)}finally{link.removeAttribute('aria-busy');link.classList.remove('is-loading')}};
  const zip=async(path:string)=>{
    async function* entries(){for(const file of files.filter(file=>file.path.startsWith(path))){if(disposed)return;yield {name:file.path.slice(path.length),input:await file.read()}}}
    save(await downloadZip(entries()).blob(),(path.split('/').filter(Boolean).at(-1)||options.title)+'.zip');
  };
  const action=(label:string,callback:()=>void,cls='toolbar-link')=>{const button=el('button',label,cls);button.type='button';button.onclick=callback;toolbar.append(button);return button};
  const up=action('↩ Up One Level',()=>browse(parent()));
  if(options.snapshot)action('⌂ Snapshot Page',options.snapshot);
  if(options.output)action('Open output',options.output);
  const download=action('⬇ Download Zip',()=>{void busy(download,()=>zip(prefix))},'toolbar-link archivebox-zip-button');
  download.prepend(el('span',undefined,'archivebox-zip-spinner'));
  const parent=()=>prefix.split('/').slice(0,-2).join('/')+(prefix.split('/').length>2?'/':'');
  const previewFiles=new WeakMap<Element,DirectoryFile>();
  const previews=new IntersectionObserver(items=>{for(const item of items){if(!item.isIntersecting)continue;previews.unobserve(item.target);const file=previewFiles.get(item.target)!;const token=generation;
    void(async()=>{if(item.target.tagName==='IMG'){const url=typeof file.url==='function'?await file.url():file.url||objectURL(await file.read());if(!disposed&&token=[REDACTED] as HTMLImageElement).src=url}
      else {const text=await(await file.read()).text();if(!disposed&&token=[REDACTED],12000)}})().catch(()=>{if(!disposed&&token=[REDACTED]'span','📄','entry-icon'))});
  }},{rootMargin:'100px'});
  function applyFilter(){let count=0;for(const row of tbody.querySelectorAll<HTMLTableRowElement>('.directory-entry:not(.parent)')){row.hidden=!row.dataset.name!.toLowerCase().includes(filter.value.toLowerCase());if(!row.hidden)count++}get('#visible-file-count').textContent=String(count);const empty=get('.empty-state');empty.toggleAttribute('hidden',count>0);empty.textContent=filter.value?'No matching files.':'This directory is empty.'}
  function sort(){const rows=[...tbody.querySelectorAll<HTMLTableRowElement>('.directory-entry:not(.parent)')];rows.sort((a,b)=>{const folders=Number(b.classList.contains('folder'))-Number(a.classList.contains('folder'));if(folders)return folders;const comparison=sortKey==='size'?Number(a.dataset.size)-Number(b.dataset.size):a.dataset[sortKey]!.localeCompare(b.dataset[sortKey]!,undefined,{numeric:true,sensitivity:'base'});return direction*comparison||a.dataset.name!.localeCompare(b.dataset.name!,undefined,{numeric:true})});rows.forEach(row=>tbody.append(row));root.querySelectorAll('th[aria-sort]').forEach(header=>header.setAttribute('aria-sort','none'));get(`[data-sort="${sortKey}"]`).parentElement!.setAttribute('aria-sort',direction===1?'ascending':'descending')}
  function browse(path:string){prefix=path;generation++;previews.disconnect();tbody.replaceChildren();filter.value='';up.hidden=!prefix;get('.directory-title').textContent=prefix?`${options.title} / ${prefix}`:options.title;
    const items=new Map<string,{path:string;name:string;directory:boolean;file?:DirectoryFile}>();
    for(const file of files){if(!file.path.startsWith(prefix))continue;const tail=file.path.slice(prefix.length),name=tail.split('/')[0]!;const directory=tail.includes('/');items.set(name,{name,path:prefix+name+(directory?'/':''),directory,file:directory?undefined:file})}
    function row(item:{name:string;path:string;directory:boolean;file?:DirectoryFile},isParent=false){const {file,directory}=item,tr=el('tr',undefined,'directory-entry'+(isParent?' parent':directory?' folder':''));tr.dataset.name=item.name;tr.dataset.size=String(file?.size??-1);tr.dataset.type=directory?'Directory':file!.mime;
      const name=el('td'),link=el('a',undefined,'directory-link');link.href=file?.href|| (typeof file?.url==='string'?file.url:'#');link.title=file?.title||item.path;
      if(directory||file?.open||!file?.href){link.onclick=event=>{event.preventDefault();if(directory)browse(item.path);else void Promise.resolve(file!.open?file!.open():open(file!)).catch(report)}}
      let icon:HTMLElement=el('span',isParent?'↩':directory?'📁':'📄','entry-icon');
      if(file&&file.size!==undefined&&file.size<100*1024){if(file.mime.startsWith('image/')){const img=el('img',undefined,'entry-preview');img.alt='';img.loading='lazy';img.decoding='async';icon=img}
        else if(file.mime.startsWith('text/')||/(?:^|[.+/-])(?:json|xml|javascript|ecmascript|yaml|toml|graphql|sql)(?:[.+/-]|$)/.test(file.mime)||/\.(log|jsonl|toml)$/.test(file.path))icon=el('pre','…','entry-preview');
        if(icon.className==='entry-preview'){previewFiles.set(icon,file);previews.observe(icon)}}
      icon.setAttribute('aria-hidden','true');const label=el('span',undefined,'entry-label'),filename=el('span',item.name+(directory&&!isParent?'/':''),'entry-name');filename.title=item.name;label.append(filename);link.append(icon,label);name.append(link);
      const type=el('td',directory?'Directory':file!.mime,'entry-type');type.title=type.textContent!;const last=el('td');
      if(!isParent){const button=el('a','⬇','entry-download');button.href=typeof file?.url==='string'?file.url:'#';button.download=item.name+(directory?'.zip':'');button.title=`Download ${item.name}`;button.setAttribute('aria-label',button.title);button.onclick=event=>{event.preventDefault();void busy(button,async()=>{if(directory)await zip(item.path);else save(await file!.read(),item.name)})};last.append(button)}
      tr.append(name,el('td',directory?'—':bytes(file!.size),'entry-size'),type,last);tbody.append(tr);
    }
    if(prefix)row({name:'../',path:parent(),directory:true},true);items.forEach(item=>row(item));sort();applyFilter();
  }
  async function open(file:DirectoryFile){const url=typeof file.url==='function'?await file.url():file.url||objectURL(await file.read());if(disposed)return;const link=el('a');link.href=url;link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove()}
  filter.oninput=applyFilter;
  root.querySelectorAll<HTMLButtonElement>('[data-sort]').forEach(button=>{button.onclick=()=>{direction=sortKey===button.dataset.sort?-direction:1;sortKey=button.dataset.sort!;sort()}});
  browse('');
  return()=>{disposed=true;generation++;previews.disconnect();urls.forEach(url=>URL.revokeObjectURL(url));root.replaceChildren()};
}

